import subprocess,re,sys
def mapper(f):
    out=subprocess.run(['git','diff','-U0','9d0147ff9e','d89fc0fda4','--',f],capture_output=True,text=True).stdout
    hunks=[]
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@',out,re.M):
        a=int(m.group(1)); al=int(m.group(2) or 1); b=int(m.group(3)); bl=int(m.group(4) or 1)
        hunks.append((a,al,b,bl))
    def mp(line):
        off=0
        for a,al,b,bl in hunks:
            end=a+al-1 if al>0 else a
            if al==0:
                if line>a: off=(b+bl-1)-a
                continue
            if line>end: off=(b+bl-1)-end
            elif line>=a: return f"{line} (edited; hunk -> {b},{bl})"
        return line+off
    return mp,hunks
f=sys.argv[1]; mp,h=mapper(f)
